for map_name,ex in expected.items():
 rows=[x for x in group["encounters"] if x["map"]==map_name]
 assert len(rows)==2 and {x["base_label"] for x in rows}==set(ex["labels"])
 for row in rows:
  land=row["land_mons"]
  assert land["encounter_rate"]==ex["rate"] and len(land["mons"])==12
  pct=defaultdict(int)
  for mon,weight,slot in zip(land["mons"],weights,ex["slots"]):
   assert mon==slot,(map_name,row["base_label"],mon,slot)
   assert mon["species"] in ex["pcts"]
   assert 1<=mon["min_level"]==mon["max_level"]<=100
   pct[mon["species"]]+=weight
  assert dict(pct)==ex["pcts"],(map_name,pct)
 assert rows[0]["land_mons"]==rows[1]["land_mons"],map_name
